fields.template:
{% load judicialfilters %}

<div class="papper">
    <div>{% include "judicial/lawsuit/header.html" %}</div>

    <div class="field">
        <div>
            <div class="label">Triagem:</div>
            <div class="value">{{ triage.number }}</div>
        </div>

        <div class="column-two">
            <div class="label">Criado:</div>
            <div class="value">{{ created_at }}</div>
        </div>

        <div>
            <div class="label">Criado por:</div>
            <div class="value">{{ created_by }}</div>
        </div>

        {% if modified_at %}
        <div class="column-two">
            <div class="label">Modificado:</div>
            <div class="value">{{ modified_at }}</div>
        </div>
        {% endif %}

        {% if modified_by %}
        <div class="column-two">
            <div class="label">Modificado por:</div>
            <div class="value">{{ modified_by }}</div>
        </div>
        {% endif %}

        <div style="clear:both"></div>
    </div>

    <div>
        <h2 class="title-1 top-space-3">Distribuição do Procedimento</h2>

        {% if triage.parts %}
            {% for part in triage.parts %}
            <div class="distribution">
                <h3 class="location">{{ part.title }}</h3>
                <div class="info">
                    <div class="label">Localidades :</div>
                    {% if part.locations %}
                    <div class="value">
                        <ul>
                        {% for location in part.locations %}
                            <li>{{ location.name }}</li>
                        {% endfor %}
                        </ul>
                    </div>
                    {% else %}
                    <div>Não foi indicada nenhuma localidade até o momento.</div>
                    {% endif %}

                    <div class="label">Órgãos de Execução no sorteio :</div>
                    {% if part.concurrence %}
                    <div class="value">
                        <ul>
                        {% for tc in part.concurrence %}
                            <li>
                                {% if tc.incident_type == 2 %}
                                <span style="font-weight:bold">
                                {% elif tc.incident_type == 3 %}
                                <span style="text-decoration:line-through;">
                                {% else %}
                                <span>
                                {% endif %}
                                    {{ tc.name }}
                                </span>
                                {% if tc.argumentation %}
                                <div class="detail">
                                    <h3>Com {{ tc.incident }}</h3>
                                    {{ tc.argumentation | safely }}
                                </div>
                                {% endif %}
                            </li>
                        {% endfor %}
                        </ul>
                    </div>
                    {% else %}
                    <div>Não foi feita a busca por concorrencia até o momento.</div>
                    {% endif %}


                    <div class="label">Distribuir para :</div>
                    <div class="value">
                    {% if part.distributed %}
                        <span class="bold">{{ part.distributed.nome }}</span>
                    {% else %}
                        <span>Ainda não foi distribuido para nenhum Órgão de Execução.</span>
                    {% endif %}
                    </div>

                    {% if part.effected_by %}
                    <div>
                        A triagem foi efetivada pelo servidor <span style="font-weight:bold">{{ part.effected_by }}</span>
                        na data <span style="font-weight:bold">{{ part.effected_at }}</span>.
                    </div>
                    {% else %}
                    <div style="color:red">Esta triagem ainda não foi distribuido.</div>
                    {% endif %}
                </div>
            </div>
            {% endfor %}
        {% else %}
            <div class="distribution">
                <h3>Ainda não foi feita a divisão dos assuntos.</h3>
            </div>
        {% endif %}
    </div>

    {% if doc.attaches.filter %}
        <div style="margin: 2em 0">
            <h3 style="margin-bottom:0.7em">Anexos</h3>
            {% for attach in doc.attaches.filter %}
                <div style="padding:0.5em 0">
                    <a href="{{ attach.file_descriptor.permalink }}" title="{{ attach.title }}">
                        {{ attach.file_descriptor.filename }}
                    </a>
                    <div><small>URL: http://athenas.developer.ti{{ attach.file_descriptor.permalink }}</small></div>
                    <div><small>MD5: {{ attach.file_descriptor.file }}</small></div>
                </div>
            {% endfor %}
        </div>
    {% endif %}
</div>

{% load judicialfilters %}

<div class="papper">
    <div>{% include "judicial/lawsuit/header.html" %}</div>

    <div><h2>Arquivamento por esta em outro Procedimento {% if rejection.other_lawsuit == 1 %}Extrajudicial{% else %}Judicial{% endif %}</h2></div>
    <div><small>Noticia de Fato : {{ doc.lawsuit.origin.codigo }} - {{ doc.lawsuit.cache_number }}</small></div>

    {% if rejection.other_lawsuit == 1 %}
    <div class="paragraph-text">
        A Noticia de Fato com número <span class="bold">{{ doc.lawsuit.origin.codigo }}</span> já encontra-se sendo
        investigado no Procedimento Extrajudicial <span class="bold">{{ doc.other_lawsuit_number }}</span>.
        {% if doc.despatch %}
        {% if rejection.execution_organ.responsavel.pessoa_fisica.sexo == 'M' %}
        O Promotor de Justiça
        {% else %}
        A Promotora de Justiça
        {% endif %}
        <span class="bold">{{ rejection.execution_organ.responsavel.pessoa_fisica }}</span>
        ainda fez a seguinte observação quanto a Noticia de Fato:
        {% endif %}
    </div>
    {% else %}
    <div class="paragraph-text">
        A Noticia de Fato com número <span class="bold">{{ doc.lawsuit.origin.codigo }}</span> já encontra-se sendo
        investigado no Procedimento Judicial <span class="bold">{{ doc.other_lawsuit_number }}</span> que corre no
        <span class="bold">{{ doc.other_lawsuit_organ.nome }}</span>.
        {% if doc.despatch %}
        {% if rejection.execution_organ.responsavel.pessoa_fisica.sexo == 'M' %}
        O Promotor de Justiça
        {% else %}
        A Promotora de Justiça
        {% endif %}
        <span class="bold">{{ rejection.execution_organ.responsavel.pessoa_fisica }}</span>
        ainda fez a seguinte observação quanto a Noticia de Fato:
        {% endif %}
    </div>
    {% endif %}

    {% if doc.despatch %}
    <div class="paragraph-text">{{ doc.despatch | safely }}</div>
    {% endif %}

    <div class="paragraph-text">
        Desta forma a Noticia de Fato <span class="bold">{{ doc.lawsuit.origin.codigo }}</span> passa a ser considerada arquivada
        devendo o <span class="bold">{{ doc.lawsuit.origin.interessado }}</span> acompanha o andamento da noticia de fato no procedimento
        mencionado anteriormente.
    </div>

    {% if doc.attaches.filter %}
        <div style="margin: 2em 0">
            <h3 style="margin-bottom:0.7em">Anexos</h3>
            {% for attach in doc.attaches.filter %}
                <div style="padding:0.5em 0">
                    <a href="{{ attach.file_descriptor.permalink }}" title="{{ attach.title }}">
                        {{ attach.file_descriptor.filename }}
                    </a>
                    <div><small>URL: http://athenas.developer.ti{{ attach.file_descriptor.permalink }}</small></div>
                    <div><small>MD5: {{ attach.file_descriptor.file }}</small></div>
                </div>
            {% endfor %}
        </div>
    {% endif %}

    <div style="text-align:center; padding-top: 2.5em">
        <div style="padding: 4em 0">{{ rejection.execution_organ.localidade.nome }}, {{ rejection.modified_at | date:'d \d\e F \d\e Y' }}</div>
        <div><span class="bold">{{ rejection.execution_organ.responsavel.pessoa_fisica }}</span></div>
        <div><span style="font-size: 0.6em">{{ rejection.execution_organ.nome }}</span></div>
    </div>
</div>

{% load judicialfilters %}

{% block body-header %}
    <div>
        <h2 class="title-1" style="text-align:center;">{{ doc.codename }} {{ convocation.cached_number }}</h2>
        <small>Noticia de Fato: {{ doc.lawsuit.origin.codigo }} - Procedimento: {{ doc.lawsuit.cache_number }}</small>
    </div>
{% endblock %}

{% block body-content %}
	<div class="paragraph-text">
        {{ convocation.convocation | safely }}
	</div>

	{% if doc.attaches.filter %}
        <div style="margin: 2em 0">
            <h3 style="margin-bottom:0.7em">Anexos</h3>
            {% for attach in doc.attaches.filter %}
                <div style="padding:0.5em 0">
                    <a href="{{ attach.file_descriptor.permalink }}" title="{{ attach.title }}">
                        {{ attach.file_descriptor.filename }}
                    </a>
                    <div><small>URL: http://athenas.developer.ti{{ attach.file_descriptor.permalink }}</small></div>
                    <div><small>MD5: {{ attach.file_descriptor.file }}</small></div>
                </div>
            {% endfor %}
        </div>
    {% endif %}

	{% if doc.signed_by %}
		{% with modified_at=doc.signed_at %}
		{% include "judicial/lawsuit/owner_sign.html" %}
		{% endwith %}
	{% endif %}
{% endblock %}
